import 'package:agora_rtc_engine/agora_rtc_engine.dart';
import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'main.dart'; // onde tem LiveRoom, LiveUser, roxo, preto, dourado

class RoomPage extends StatefulWidget {
  final LiveRoom room; 
    final LiveUser user; 
      final VoidCallback onChanged;
        const RoomPage({super.key, required this.room, required this.user, required this.onChanged});
          @override State<RoomPage> createState() => _RoomPageState();
          }

          class _RoomPageState extends State<RoomPage> {
            final message = TextEditingController();
              bool mic = false;
                bool joinedVoice = false;
                  late RtcEngine agoraEngine;
                    List<Map<String, dynamic>> realMessages = [];
                      List<String> realSeats = List.filled(8, '');

                        // PEGA DE GRAÇA EM: console.agora.io
                          final String agoraAppId = "SEU_APP_ID_DA_AGORA_AQUI"; 

                            @override
                              void initState() {
                                  super.initState();
                                      _loadMessages();
                                          _loadSeats();
                                              _listenRealtime();
                                                  _initAgora();
                                                    }

                                                      Future<void> _initAgora() async {
                                                          agoraEngine = createAgoraRtcEngine();
                                                              await agoraEngine.initialize(RtcEngineContext(appId: agoraAppId));
                                                                  await agoraEngine.enableAudio();
                                                                      await agoraEngine.setChannelProfile(ChannelProfileType.channelProfileLiveBroadcasting);
                                                                          await agoraEngine.setClientRole(role: ClientRoleType.clientRoleBroadcaster);
                                                                              
                                                                                  agoraEngine.registerEventHandler(RtcEngineEventHandler(
                                                                                        onJoinChannelSuccess: (c, uid) {
                                                                                                debugPrint("Entrou na voz! uid: $uid");
                                                                                                      },
                                                                                                            onUserJoined: (c, uid, elapsed) {
                                                                                                                    if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Alguém entrou na voz: $uid')));
                                                                                                                          }
                                                                                                                              ));
                                                                                                                                }

                                                                                                                                  Future<void> _loadMessages() async {
                                                                                                                                      final res = await Supabase.instance.client.from('room_messages').select().eq('room_id', widget.room.id).order('created_at');
                                                                                                                                          if(mounted) setState(() { realMessages = List<Map<String, dynamic>>.from(res); });
                                                                                                                                            }

                                                                                                                                              Future<void> _loadSeats() async {
                                                                                                                                                  final res = await Supabase.instance.client.from('room_seats').select().eq('room_id', widget.room.id);
                                                                                                                                                      List<String> seatsTemp = List.filled(8, '');
                                                                                                                                                          for (var row in res) {
                                                                                                                                                                int idx = row['seat_index']; 
                                                                                                                                                                      if (idx >=0 && idx <8) seatsTemp[idx] = row['user_name'] ?? '';
                                                                                                                                                                          }
                                                                                                                                                                              if(mounted) setState(() { realSeats = seatsTemp; });
                                                                                                                                                                                }

                                                                                                                                                                                  void _listenRealtime() {
                                                                                                                                                                                      Supabase.instance.client
                                                                                                                                                                                            .channel('room-${widget.room.id}')
                                                                                                                                                                                                  .onPostgresChanges(event: PostgresChangeEvent.all, schema: 'public', table: 'room_messages', filter: PostgresChangeFilter(type: PostgresChangeFilterType.eq, column: 'room_id', value: widget.room.id), callback: (payload) { _loadMessages(); })
                                                                                                                                                                                                        .onPostgresChanges(event: PostgresChangeEvent.all, schema: 'public', table: 'room_seats', filter: PostgresChangeFilter(type: PostgresChangeFilterType.eq, column: 'room_id', value: widget.room.id), callback: (payload) { _loadSeats(); })
                                                                                                                                                                                                              .subscribe();
                                                                                                                                                                                                                }

                                                                                                                                                                                                                  Future<void> toggleVoice() async {
                                                                                                                                                                                                                      if (!joinedVoice) {
                                                                                                                                                                                                                            // NO CODESPACES/WEB NÃO PRECISA DE permission_handler
                                                                                                                                                                                                                                  await agoraEngine.joinChannel(token: "", channelId: widget.room.id, uid: 0, options: const ChannelMediaOptions());
                                                                                                                                                                                                                                        setState(() { joinedVoice = true; mic = true; });
                                                                                                                                                                                                                                              if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('🎙️ VOZ REAL LIGADA! Você está ao vivo!')));
                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                        await agoraEngine.leaveChannel();
                                                                                                                                                                                                                                                              setState(() { joinedVoice = false; mic = false; });
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                      Future<void> sendReal() async {
                                                                                                                                                                                                                                                                          if (message.text.trim().isEmpty) return;
                                                                                                                                                                                                                                                                              await Supabase.instance.client.from('room_messages').insert({
                                                                                                                                                                                                                                                                                    'room_id': widget.room.id,
                                                                                                                                                                                                                                                                                          'user_id': widget.user.id,
                                                                                                                                                                                                                                                                                                'user_name': widget.user.name,
                                                                                                                                                                                                                                                                                                      'message': message.text.trim()
                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                              message.clear();
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                  Future<void> claimSeatReal(int index) async {
                                                                                                                                                                                                                                                                                                                      if (realSeats[index].isNotEmpty && realSeats[index] != widget.user.name) {
                                                                                                                                                                                                                                                                                                                            ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Lugar ocupado!')));
                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                          if (realSeats[index] == widget.user.name) {
                                                                                                                                                                                                                                                                                                                                                await Supabase.instance.client.from('room_seats').delete().eq('room_id', widget.room.id).eq('seat_index', index);
                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                          if (realSeats.contains(widget.user.name)) {
                                                                                                                                                                                                                                                                                                                                                                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Você já está em um assento!')));
                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                      await Supabase.instance.client.from('room_seats').upsert({
                                                                                                                                                                                                                                                                                                                                                                                              'room_id': widget.room.id, 'seat_index': index, 'user_id': widget.user.id, 'user_name': widget.user.name
                                                                                                                                                                                                                                                                                                                                                                                                    }, onConflict: 'room_id,seat_index');
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                            @override
                                                                                                                                                                                                                                                                                                                                                                                                              void dispose() { 
                                                                                                                                                                                                                                                                                                                                                                                                                  agoraEngine.leaveChannel(); 
                                                                                                                                                                                                                                                                                                                                                                                                                      agoraEngine.release(); 
                                                                                                                                                                                                                                                                                                                                                                                                                          message.dispose(); 
                                                                                                                                                                                                                                                                                                                                                                                                                              super.dispose(); 
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                  @override
                                                                                                                                                                                                                                                                                                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                              appBar: AppBar(title: Text(widget.room.name)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: ListView(padding: const EdgeInsets.all(14), children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                            Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: const EdgeInsets.all(18), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: BorderRadius.circular(20), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        gradient: const LinearGradient(colors: [roxo, preto]), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: Border.all(color: joinedVoice ? Colors.green : dourado, width: 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ), 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Column(children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Text(joinedVoice ? "🟢 AO VIVO" : "⚫ OFFLINE", style: TextStyle(color: joinedVoice ? Colors.green : Colors.white, fontWeight: FontWeight.bold)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ElevatedButton.icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onPressed: toggleVoice, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                icon: Icon(joinedVoice ? Icons.mic : Icons.mic_off),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label: Text(joinedVoice ? "SAIR DA VOZ" : "ENTRAR NA VOZ"),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: ElevatedButton.styleFrom(backgroundColor: joinedVoice ? Colors.red : Colors.green),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  GridView.builder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shrinkWrap: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              physics: const NeverScrollableScrollPhysics(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 4, childAspectRatio: 0.8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          itemCount: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        itemBuilder: (context, index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bool isMe = realSeats[index] == widget.user.name;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bool isEmpty = realSeats[index].isEmpty;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return GestureDetector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onTap: () => claimSeatReal(index),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                margin: const EdgeInsets.all(4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: isEmpty ? Colors.grey[900] : (isMe ? dourado : Colors.deepPurple),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: BorderRadius.circular(12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      border: Border.all(color: isMe ? Colors.white : Colors.transparent)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Icon(isEmpty ? Icons.chair : Icons.person, color: Colors.white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Text(isEmpty ? "Vazio" : realSeats[index], style: const TextStyle(color: Colors.white, fontSize: 10), overflow: TextOverflow.ellipsis),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // CHAT REAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 300,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              decoration: BoxDecoration(color: Colors.grey[900], borderRadius: BorderRadius.circular(12)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: ListView.builder(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    itemCount: realMessages.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                itemBuilder: (context, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var m = realMessages[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return ListTile(dense: true, title: Text(m['message'] ?? '', style: const TextStyle(color: Colors.white)), subtitle: Text(m['user_name'] ?? '', style: const TextStyle(color: Colors.grey)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Row(children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Expanded(child: TextField(controller: message, decoration: InputDecoration(hintText: "Fala aí, ${widget.user.name}...", filled: true, fillColor: Colors.grey[900], border: OutlineInputBorder(borderRadius: BorderRadius.circular(12))))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(width: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        IconButton.filled(onPressed: sendReal, icon: const Icon(Icons.send))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }u